def report_oam_kpi(oam_kpi_results=None, oam_kpi_targets=None, variant=None, log_warn=True, delta_to_report='main'):
    """
    Report oam kpi to ReP. Results are presented in ReP under link:
        https://rep-portal.wroclaw.nsn-rdnet.net/reports/kpi/
    :param oam_kpi_results: result calculated by taf.ul.oam_kpi_calculations library.
                            It's not mandatory parameter, If you perform oam kpi calculations during tests,
                            you don't need to pass results. It will be taken automatically.
    :param oam_kpi_targets: optional - dict, targets for kpi in following structure:

                            OAM_KPI_TARGETS = {
                                'kpi1a': 100,
                                'kpi5': 30,
                            }

                            If you need to define targets for each RAT, you could do this as below:
                            OAM_KPI_TARGETS = {
                                'kpi1a': {
                                    'GENERAL': 20,
                                    'rat': {
                                        '5G': 12,
                                        '4G': 11,
                                        '3G': 15,
                                        '2G': 20,
                                    }
                                },
                                'kpi5': {
                                    'GENERAL': 30,
                                    'rat': {
                                        '5G': 22,
                                        '4G': 21,
                                        '3G': 25,
                                        '2G': 30,
                                    }
                                }
                                'kpi51a': {
                                    'GENERAL': 30,
                                    'product_name': {
                                        'AQQJ': 200,
                                        'AHPB': 300,
                                    }
                                }
                            }

                            If not passed, targets will not be send to ReP
                            You can also import OAM_KPI_TARGETS by Variables(then don't need to pass to KW)
    :param variant: KPI variant(optional) - in the short, In most cases it is product name of device involved for particular KPI.
                    eg: we have KPI5 - restart BBMOD - we need to know product code of restarted BBMOD.
                    Sample of 'full' variant:
                    variant = {
                        "bbmod": ["ABIA"],
                        "smod": ["ASIK"],
                        "rmod": ["APHG"],
                        "rat": ["5G"],
                        "hwf": True
                    }
                    Usually only one key is sufficient to pass(because particular KPI involve one device)
                    eg for KPI5(reset BBMOD) proper structure is as below:
                    variant = {
                        "bbmod": ["ABIA"]
                    }
    :param log_warn: Flag True/False - enable print warning when delta for some iteration is None
    :param delta_to_report: Specifies which delta to report. Possible values are:
                            'main' - for reporting the main delta,
                            'bts_detailed' - for reporting all main deltas under `bts_detailed_results`,
                            'MRBTS-1234' - for reporting a specific MRBTS,
                            'MRBTS-1234,MRBTS-3345' or ['MRBTS-1234', 'MRBTS-3345'] - for reporting multiple
                            specific MRBTS.
    :return:
    """
    if oam_kpi_results is None:
        oam_kpi_calculations = _get_oam_kpi_calculations_instance()
        oam_kpi_results = oam_kpi_calculations.get_results()
    if oam_kpi_targets is None:
        oam_kpi_targets = BuiltIn().get_variable_value('${{{}}}'.format('OAM_KPI_TARGETS'), None)

    ReportOamKpi().report_oam_kpi(oam_kpi_results, oam_kpi_targets, variant, log_warn=log_warn,
                                  delta_to_report=delta_to_report)


def report_oam_kpi_success_rate(kpi_name, passed_iterations, executed_iterations):
    """

    :param kpi_name: kpi name eg kpi1, kpi51
    :param passed_iterations: passed iteration
    :param executed_iterations: all executed iterations
    :return:
    """
    ReportOamKpi().report_oam_kpi_success_rate(kpi_name, passed_iterations, executed_iterations)


def calculate_summary_results_and_save_to_file(oam_kpi_results=None, oam_kpi_targets=None, oam_kpi_avg_targets=None,
                                               kpi_summary_file_path=None, oam_kpi_success_rate_targets=None,
                                               oam_kpi_thresholds=None, skipped_iterations=None):
    """
    Calculate summary report(all passed/failed iteration) and save to json file.
        Sample part of file structure:
        {
            "kpi1a": {
                "avg": 412.59,
                "avg_from_passed_iter": 412.59,
                "executed": 20,
                "failed": 0,
                "not_calculated": 0,
                "max": 421.15,
                "max_from_passed_iter": 421.15,
                "min": 400.9,
                "min_from_passed_iter": 400.9,
                "passed": 20,
                "ratio": 1.0,
                "results": {
                    "iteration_1": {
                        "delta": 407.02,
                        "status": "PASSED"
                    },
                    "iteration_10": {
                        "delta": 417.07,
                        "status": "PASSED"
                    },
                    ....
                    ....
    :param oam_kpi_results: result calculated by taf.ul.oam_kpi_calculations library.
                        It's not mandatory parameter, If you perform oam kpi calculations during tests,
                        you don't need to pass results. It will be taken automatically.
    :param oam_kpi_targets: optional - dict, targets for kpi in following structure:

                        OAM_KPI_TARGETS = {
                            'kpi1a': 100,
                            'kpi5': 30,
                        }

                        If you need to define targets for each RAT, you could do this as below:
                        OAM_KPI_TARGETS = {
                            'kpi1a': {
                                'GENERAL': 20,
                                '5G': 12,
                                '4G': 11,
                                '3G': 15,
                                '2G': 20,
                            },
                            'kpi5': {
                                'GENERAL': 30,
                                '5G': 22,
                                '4G': 21,
                                '3G': 25,
                                '2G': 30,
                            }
                        }

                        If not passed, targets will not be send to ReP
                        You can also import OAM_KPI_TARGETS by Variables(then don't need to pass to KW)
    :param oam_kpi_avg_targets: optional - dict, average targets for kpi in structure the same as oam_kpi_targets param
    :param oam_kpi_success_rate_targets: optional - dict, success rate targets for kpi in following structure:
                        OAM_KPI_SUCCESS_RATE_TARGETS = {
                            'kpi1a': 0.99,
                            'kpi5': 1,
                        }
    :param oam_kpi_thresholds: optional - dict, thresholds which determine if iteration is valid or not.
                        Structure is similar like in other params.
                        OAM_KPI_THRESHOLDS = {
                            'kpi1a': 1200,
                            'kpi5': 800,
                        }
    :param kpi_summary_file_path: path to summary file eg ${OUTPUT_DIR}/kpi_summary_results.json
    :param skipped_iterations: dict with skipped iterations for particular KPI
                               e.g. {'kpi1a': [2,5], 'kpi5': [1,3,4]}
    :return all_results
    """

    if oam_kpi_results is None:
        oam_kpi_calculations = _get_oam_kpi_calculations_instance()
        oam_kpi_results = oam_kpi_calculations.get_results()
    if oam_kpi_targets is None:
        oam_kpi_targets = BuiltIn().get_variable_value('${{{}}}'.format('OAM_KPI_TARGETS'))
    if oam_kpi_avg_targets is None:
        oam_kpi_avg_targets = BuiltIn().get_variable_value('${{{}}}'.format('OAM_KPI_AVG_TARGETS'))
    if oam_kpi_success_rate_targets is None:
        oam_kpi_success_rate_targets = BuiltIn().get_variable_value('${{{}}}'.format('OAM_KPI_SUCCESS_RATE_TARGETS'))
    if oam_kpi_thresholds is None:
        oam_kpi_thresholds = BuiltIn().get_variable_value('${{{}}}'.format('OAM_KPI_THRESHOLDS'))
    if kpi_summary_file_path is None:
        log_dir = BuiltIn().get_variable_value('${{{}}}'.format('OUTPUT_DIR'))
        kpi_summary_file_path = os.path.join(log_dir, 'kpi_summary_results.json')

    return ReportOamKpi().calculate_summary_results_and_save_to_file(oam_kpi_results, oam_kpi_targets,
                                                                     oam_kpi_avg_targets, kpi_summary_file_path,
                                                                     oam_kpi_success_rate_targets, oam_kpi_thresholds,
                                                                     skipped_iterations)


def report_reference_configuration_id(ref_configuration_id=None):
    rep_ref_conf_id(ref_configuration_id)


def set_target(kpi_name, target, technology='GENERAL'):
    oam_kpi_targets = BuiltIn().get_variable_value('${{{}}}'.format('OAM_KPI_TARGETS'), None)
    if not oam_kpi_targets:
        oam_kpi_targets = {kpi_name: {technology: target}}
        BuiltIn().set_test_variable('${{{}}}'.format('OAM_KPI_TARGETS'), oam_kpi_targets)
    else:
        if kpi_name not in oam_kpi_targets:
            oam_kpi_targets[kpi_name] = {}
        oam_kpi_targets[kpi_name][technology] = target

    logging.debug("CURRENT TARGETS {}".format(oam_kpi_targets))


def _get_oam_kpi_calculations_instance():
    oam_kpi_instance_names = ['taf.ul.oam_kpi_calculations', 'oam_kpi_calculations', 'oam_kpi']
    for oam_kpi_instance_name in oam_kpi_instance_names:
        try:
            instance = BuiltIn().get_library_instance('{}'.format(oam_kpi_instance_name), None)
            if instance:
                return instance
        except RuntimeError:
            pass


